#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/irq_offload.h>
#include <zephyr/timing/timing.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_isr, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_yield, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_sleep, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_create, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_cancel, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_suspend, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_resume, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_abort, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_priority, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_join, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_custom_data, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_foreach, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_name, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_user_mode, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_cpu_mask, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_deadline, STACK_SIZE);
K_THREAD_STACK_DEFINE(tstack_timeslice, STACK_SIZE);

struct k_thread thread_data;
struct k_thread thread_data_isr;
struct k_thread thread_data_yield;
struct k_thread thread_data_sleep;
struct k_thread thread_data_create;
struct k_thread thread_data_cancel;
struct k_thread thread_data_suspend;
struct k_thread thread_data_resume;
struct k_thread thread_data_abort;
struct k_thread thread_data_priority;
struct k_thread thread_data_join;
struct k_thread thread_data_custom_data;
struct k_thread thread_data_foreach;
struct k_thread thread_data_name;
struct k_thread thread_data_user_mode;
struct k_thread thread_data_cpu_mask;
struct k_thread thread_data_deadline;
struct k_thread thread_data_timeslice;

volatile int thread_evidence;
volatile int thread_idx;
volatile int thread_order[10];
volatile int thread_timeout_order[10];
volatile int thread_timeout_idx;

K_SEM_DEFINE(sem_yield, 0, 1);
K_SEM_DEFINE(sem_sleep, 0, 1);
K_SEM_DEFINE(sem_create, 0, 1);
K_SEM_DEFINE(sem_cancel, 0, 1);
K_SEM_DEFINE(sem_suspend, 0, 1);
K_SEM_DEFINE(sem_resume, 0, 1);
K_SEM_DEFINE(sem_abort, 0, 1);
K_SEM_DEFINE(sem_priority, 0, 1);
K_SEM_DEFINE(sem_join, 0, 1);
K_SEM_DEFINE(sem_custom_data, 0, 1);
K_SEM_DEFINE(sem_foreach, 0, 1);
K_SEM_DEFINE(sem_name, 0, 1);
K_SEM_DEFINE(sem_user_mode, 0, 1);
K_SEM_DEFINE(sem_cpu_mask, 0, 1);
K_SEM_DEFINE(sem_deadline, 0, 1);
K_SEM_DEFINE(sem_timeslice, 0, 1);
K_SEM_DEFINE(sem_timer, 0, 1);

#define THREAD_PRIORITY K_PRIO_PREEMPT(0)

void thread_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_yield);
}

void k_yield_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	zassert_equal(thread_evidence, 1, "thread_evidence not equal to 1");
	thread_evidence++;
	k_sem_give(&sem_yield);
}

void k_sleep_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_sleep);
}

void k_thread_create_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_create);
}

void k_thread_cancel_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_cancel);
}

void k_thread_suspend_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_suspend);
}

void k_thread_resume_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_resume);
}

void k_thread_abort_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_abort);
}

void k_thread_priority_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_priority);
}

void k_thread_join_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_join);
}

void k_thread_custom_data_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_custom_data);
}

void k_thread_foreach_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_foreach);
}

void k_thread_name_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_name);
}

void k_thread_user_mode_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_user_mode);
}

void k_thread_cpu_mask_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_cpu_mask);
}

void k_thread_deadline_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_deadline);
}

void k_thread_timeslice_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	thread_order[thread_idx++] = (int)k_current_get()->base.prio;
	k_sem_give(&sem_timeslice);
}

void timer_handler(struct k_timer *timer)
{
	ARG_UNUSED(timer);

	thread_evidence++;
	k_sem_give(&sem_timer);
}

K_TIMER_DEFINE(test_timer, timer_handler, NULL);

static void *context_setup(void)
{
	thread_idx = 0;
	thread_timeout_idx = 0;
	thread_evidence = 0;
	return NULL;
}

static void context_teardown(void *data)
{
	ARG_UNUSED(data);
}

ZTEST_SUITE(context, NULL, context_setup, NULL, context_teardown, NULL);

/* Test cases */

ZTEST(context, test_k_yield)
{
	thread_evidence = 0;

	k_thread_create(&thread_data_yield, tstack_yield, STACK_SIZE,
				k_yield_entry, NULL, NULL, NULL,
				THREAD_PRIORITY, 0, K_NO_WAIT);

	thread_evidence = 1; /* Set evidence for k_yield_entry to check */
	k_yield(); /* Yield to the new thread */

	zassert_equal(k_sem_take(&sem_yield, K_FOREVER), 0, NULL);
	zassert_equal(thread_evidence, 2, "thread_evidence not 2 after k_yield_entry");
}

ZTEST(context, test_k_sleep)
{
	thread_evidence = 0;

	k_thread_create(&thread_data_sleep, tstack_sleep, STACK_SIZE,
				k_sleep_entry, NULL, NULL, NULL,
				THREAD_PRIORITY, 0, K_NO_WAIT);

	k_sleep(K_MSEC(100)); /* Allow thread to run and sleep */

	zassert_equal(k_sem_take(&sem_sleep, K_FOREVER), 0, NULL);
	zassert_equal(thread_idx, 1, "thread_idx not 1 after k_sleep_entry");
}

ZTEST(context, test_k_thread_create)
{
	thread_evidence = 0;

	k_thread_create(&thread_data_create, tstack_create, STACK_SIZE,
				k_thread_create_entry, NULL, NULL, NULL,
				THREAD_PRIORITY, 0, K_NO_WAIT);

	zassert_equal(k_sem_take(&sem_create, K_FOREVER), 0, NULL);
	zassert_equal(thread_idx, 1, "thread_idx not 1 after k_thread_create_entry");
}

ZTEST(context, test_k_thread_cancel)
{
	thread_evidence = 0;

	k_thread_create(&thread_data_cancel, tstack_cancel, STACK_SIZE,
				k_thread_cancel_entry, NULL, NULL, NULL,
				THREAD_PRIORITY, 0, K_NO_WAIT);

	k_thread_cancel(&thread_data_cancel);

	zassert_equal(k_sem_take(&sem_cancel, K_MSEC(100)), -EAGAIN, "Thread was not cancelled");
}

ZTEST(context, test_k_thread_suspend_resume)
{
	thread_evidence = 0;

	k_thread_create(&thread_data_suspend, tstack_suspend, STACK_SIZE,
				k_thread_suspend_entry, NULL, NULL, NULL,
				THREAD_PRIORITY, 0, K_NO_WAIT);

	k_thread_suspend(&thread_data_suspend);

	zassert_equal(k_sem_take(&sem_suspend, K_MSEC(100)), -EAGAIN, "Thread was not suspended");

	k_thread_resume(&thread_data_suspend);

	zassert_equal(k_sem_take(&sem_suspend, K_FOREVER), 0, NULL);
}

ZTEST(context, test_k_thread_abort)
{
	thread_evidence = 0;

	k_thread_create(&thread_data_abort, tstack_abort, STACK_SIZE,
				k_thread_abort_entry, NULL, NULL, NULL,
				THREAD_PRIORITY, 0, K_NO_WAIT);

	k_thread_abort(&thread_data_abort);

	zassert_equal(k_sem_take(&sem_abort, K_MSEC(100)), -EAGAIN, "Thread was not aborted");
}

ZTEST(context, test_k_thread_priority)
{
	thread_evidence = 0;

	k_thread_create(&thread_data_priority, tstack_priority, STACK_SIZE,
				k_thread_priority_entry, NULL, NULL, NULL,
				K_PRIO_PREEMPT(1), 0, K_NO_WAIT);

	k_thread_priority_set(&thread_data_priority, K_PRIO_PREEMPT(0));

	zassert_equal(k_sem_take(&sem_priority, K_FOREVER), 0, NULL);
	zassert_equal(thread_idx, 1, "thread_idx not 1 after k_thread_priority_entry");
	zassert_equal(thread_order[0], K_PRIO_PREEMPT(0), "Priority not set correctly");
}

ZTEST(context, test_timer_interrupts)
{
	thread_evidence = 0;

	k_timer_start(&test_timer, K_MSEC(10), K_NO_WAIT);

	/* Set thread_evidence to 1 before yielding to allow k_yield_entry to pass its assertion */
	thread_evidence = 1;

	k_thread_create(&thread_data_yield, tstack_yield, STACK_SIZE,
				k_yield_entry, NULL, NULL, NULL,
				THREAD_PRIORITY, 0, K_NO_WAIT);

	k_yield(); /* Yield to the new thread */

	zassert_equal(k_sem_take(&sem_yield, K_FOREVER), 0, NULL);
	zassert_equal(thread_evidence, 2, "thread_evidence not 2 after k_yield_entry");

	zassert_equal(k_sem_take(&sem_timer, K_FOREVER), 0, NULL);
	zassert_equal(thread_evidence, 3, "thread_evidence not 3 after timer handler");

	k_timer_stop(&test_timer);
}

